        require(address(this).balance >= 10);

        uint beforeTestBalance = address(this).balance;

        c.play{value: 10}(); if (__ESBMC_reverted()) return;

        uint afterPot = c.pot(); if (__ESBMC_reverted()) return;
        uint afterTestBalance = address(this).balance;

        bool callerReceivedPayout = afterTestBalance > beforeTestBalance - 10;

