// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {EtherLotto} from "../src/EtherLotto.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    EtherLotto c;

    function setUp() public {
        c = new EtherLotto();
    }

    function _run(uint256 unusedSeed) internal {
        vm.deal(address(this), VALUE_CAP);
        vm.deal(address(c), VALUE_CAP);
        vm.assume(address(this).balance >= 10);
        uint beforeTestBalance = address(this).balance;
        try c.play{value: 10}() {} catch { return; }
        uint256 afterPot;
        try c.pot() returns (uint256 __r) { afterPot = __r; } catch { return; }
        uint afterTestBalance = address(this).balance;
        bool callerReceivedPayout = afterTestBalance > beforeTestBalance - 10;
        assertTrue(callerReceivedPayout ? (afterPot == 0) : (afterPot > 0));
    }

    function testFuzz_run(uint256 unusedSeed) public {
        _run(unusedSeed);
    }

    receive() external payable {}
}
